  const sim = mdSimOf(url, isDev);
  if (sim && sim.game && tm && nextIso) { // DEV preview: the real line-up of a game already played, on today's page, whatever the switch, day or time say
    const pg = (games || []).find(x => x && String(x.id) === sim.game);
    if (!pg) return { ...none, why: "nogame" };
    const sheet = await mdLoadSheet(tm, pg, mdParts(new Date(pg.iso).getTime()).day, null);
    if (!sheet || sheet.count < 1) return { ...none, why: "nosheet", read: true, sheet };
    sheet.preview = "Preview: line-up from " + String(pg.oppName || "a game already played") + ", " + String(pg.iso).slice(0, 10);
    return { show: true, hold: null, sheet, why: "preview", read: true };
  }
  if (!tm || !tm.matchday || !nextIso) return none;
  const gameDay = mdParts(new Date(nextIso).getTime()).day;
  const now = sim && sim.now ? mdEpoch(gameDay, sim.now) : (nowMs || Date.now());
  const ph = mdPhase(now, gameDay, tm.mdEnd || MD_END_DEFAULT);
  if (ph.phase === "off" || ph.phase === "over") return { ...none, why: ph.phase };
  if (ph.phase === "pre") return { ...none, why: "pre", hold: { secs: 86400, until: ph.startMs } };
  if (sim && sim.score) return { ...none, why: "score" };
  const g = (games || []).filter(x => x && x.iso && x.id && /^\d{1,10}$/.test(String(x.id)) && x.status !== "void" && x.status !== "done" && mdParts(new Date(x.iso).getTime()).day === gameDay).sort((a, b) => a.iso < b.iso ? -1 : 1)[0];
  const wait = { ...none, why: "wait", hold: { secs: MD_WAIT_SECS, until: ph.endMs } };
  if (!g) return wait;
  let sheet;
  if (sim && sim.from) { // DEV: use the real sheet of a game already played in place of the one that is not there yet
    const pg = (games || []).find(x => x && String(x.id) === sim.from);
    sheet = pg ? await mdLoadSheet(tm, pg, mdParts(new Date(pg.iso).getTime()).day, null) : null;
  } else sheet = await mdLoadSheet(tm, g, gameDay, sim);
