var nl=0,tot=0,big=0,nos=0;items.forEach(function(x){if(x.logo){nl++;if(x.logo.n){tot+=x.logo.n;if(x.logo.n>big)big=x.logo.n}else nos++}});var e2=$("lgsum");if(!e2)return;
