function inboxPage(theme, isDev, hasKv) {
  const t = theme === "light" ? "light" : "dark";
  const tags = JSON.stringify(MSG_TAGS);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><title>Visitor messages</title>
<style>${MENU_CSS}.wrap.wcp{max-width:1080px}.top2{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap}.top2 h1{margin:0}.rf{display:flex;align-items:center;gap:10px}.rf small{color:#91a49a;font-size:12.5px}.rb{font:700 14px Arial,Helvetica,sans-serif;border-radius:99px;padding:9px 16px;min-height:40px;cursor:pointer;border:1px solid #2c3a34;background:#18211e;color:#e6efe9}.flt{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0 14px}.fc{font:700 13px Arial,Helvetica,sans-serif;border-radius:99px;padding:8px 13px;min-height:36px;cursor:pointer;border:1px solid #2c3a34;background:#111719;color:#cfd8d3}.fc.on{background:#2f9d57;border-color:#2f9d57;color:#fff}.fc i{font-style:normal;opacity:.75;margin-left:4px}.hd2{display:flex;align-items:center;gap:6px;font-size:13px;color:#91a49a;margin-left:auto}.ib{display:grid;grid-template-columns:minmax(0,360px) minmax(0,1fr);gap:16px;align-items:start}.lst{display:flex;flex-direction:column;gap:8px}.it{text-align:left;display:flex;flex-direction:column;gap:5px;padding:12px 14px;border-radius:12px;border:1px solid #26312d;background:#111719;color:#e6efe9;cursor:pointer;font:inherit;position:relative}.it.on{border-color:#2f9d57;background:#15201b}.it.dn{opacity:.6}.it .a{display:flex;justify-content:space-between;align-items:center;gap:8px}.it .w{font-size:12.5px;color:#91a49a}.it .s{font-size:15px;line-height:1.4;overflow-wrap:anywhere}.it .dv{font-size:12px;color:#7f948a}.it.nw .s{font-weight:700}.it.nw::before{content:"";position:absolute;left:5px;top:50%;width:6px;height:6px;margin-top:-3px;border-radius:50%;background:#7fd89a}.it.rd .s{color:#a9bbb1}.tg2{display:inline-block;font:700 11px Arial,Helvetica,sans-serif;letter-spacing:.06em;text-transform:uppercase;border-radius:6px;padding:3px 8px;white-space:nowrap}.tg-data{background:#3a1f22;color:#ff9b9b}.tg-team{background:#16283a;color:#8fc4ff}.tg-idea{background:#15301f;color:#7fe0a6}.tg-other{background:#2a2a2a;color:#cfd8d3}.mail{background:#111719;border:1px solid #26312d;border-radius:16px;overflow:hidden;min-width:0}.mt{display:flex;gap:8px;flex-wrap:wrap;padding:12px 16px;border-bottom:1px solid #26312d;background:#0f1517}.mt button,.mt a{font:700 14px Arial,Helvetica,sans-serif;border-radius:10px;padding:9px 14px;min-height:40px;cursor:pointer;border:1px solid #2c3a34;background:#18211e;color:#e6efe9;text-decoration:none;display:inline-flex;align-items:center}.mt .pr{background:#7fd19a;color:#0b1110;border-color:#7fd19a}.mt .dg{color:#f09595;border-color:#5a2f2f;margin-left:auto}.mh{padding:18px 20px 12px;display:flex;flex-direction:column;gap:12px}.sj{display:flex;gap:10px;align-items:flex-start;flex-wrap:wrap}.sj h2{margin:0;font-size:21px;line-height:1.3;flex:1;min-width:0;overflow-wrap:anywhere}.mr{display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px 14px;font-size:14px;color:#91a49a}.mr b{color:#a9bbb1;font-weight:700}.mr span{color:#dbe6df;overflow-wrap:anywhere}.bd{padding:6px 20px 24px;border-top:1px solid #26312d;margin-top:6px}.bd .tx{padding-top:18px;font-size:17px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}.ft{padding:12px 20px;border-top:1px solid #26312d;font-size:13px;color:#91a49a}.em{color:#91a49a;padding:24px 8px;font-size:15px}.msg{color:#f09595;font-size:14px;padding:0 20px 8px;min-height:18px}.bk{display:none;font:700 14px Arial,Helvetica,sans-serif;background:none;border:0;color:#7fd89a;padding:10px 16px 0;cursor:pointer}@media (max-width:760px){.ib{grid-template-columns:1fr}.ib.sel .lst{display:none}.ib:not(.sel) .mail{display:none}.bk{display:block}.mt .dg{margin-left:0}.hd2{margin-left:0}}body.light .it,body.light .mail,body.light .fc{background:#fff;border-color:#cbd8ce;color:#14201a}body.light .it.on{background:#eef6f0}body.light .mt{background:#f4f8f5;border-color:#e0e7e1}body.light .mt button,body.light .mt a,body.light .rb{background:#f4f8f5;color:#14201a;border-color:#cbd8ce}body.light .mt .pr{background:#1b7f3b;color:#fff;border-color:#1b7f3b}body.light .fc.on{background:#1b7f3b;color:#fff;border-color:#1b7f3b}body.light .mr span{color:#1b2a22}body.light .bd,body.light .ft{border-color:#e0e7e1}body.light .tg-data{background:#fde4e4;color:#a02020}body.light .tg-team{background:#e1eefc;color:#1d5a9a}body.light .tg-idea{background:#dff3e5;color:#1b6b3a}body.light .tg-other{background:#ebedeb;color:#3a4a42}</style></head><body class="${t}">${themeBoot("true")}<div class="wrap wcp"><nav class="mbar"><a class="pill" href="/admin">&lsaquo; Admin</a><button type="button" class="pill tgl">Light mode</button></nav>
<div class="top2"><div><h1>Visitor messages</h1><p class="sub" id="sub" style="margin:4px 0 0">${hasKv ? "Messages from visitors, newest first." : "No settings storage is connected, so there are no messages."}</p></div><div class="rf"><small id="upd"></small><button type="button" class="rb" id="rf">Refresh</button></div></div>
<div class="flt" id="fl"></div>
<div class="ib" id="ib"><div class="lst" id="ls"></div><div class="mail" id="dt"><div class="em">Choose a message to read it.</div></div></div>
<p class="ver">${VERSION_LABEL}${isDev ? " &middot; DEV" : ""}</p></div>${themeToggleScript}
<script>(function(){var TG=${tags},ls=document.getElementById("ls"),dt=document.getElementById("dt"),ib=document.getElementById("ib"),sub=document.getElementById("sub"),fl=document.getElementById("fl"),upd=document.getElementById("upd"),items=[],cur="",armed="",flt="all",hideDone=false,busy=false;
function e(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function fmt(iso,long){var d=new Date(iso);if(isNaN(d))return"";return d.toLocaleString("en-GB",long?{timeZone:"Europe/London",weekday:"long",day:"numeric",month:"long",year:"numeric",hour:"2-digit",minute:"2-digit"}:{timeZone:"Europe/London",day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"})}
function tag(r){return'<span class="tg2 tg-'+e(TG[r]?r:"other")+'">'+e(TG[r]||"Other")+"</span>"}
function subj(t){var s=String(t||"").replace(/\\s+/g," ").trim();return s.length>70?s.slice(0,70)+"\\u2026":s}
function api(o,cb){fetch("/api/inbox",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)}).then(function(r){return r.json().catch(function(){return{ok:false}})}).then(cb).catch(function(){cb({ok:false,error:"Check your connection."})})}
function chips(){var cnt={all:items.length};Object.keys(TG).forEach(function(k){cnt[k]=0});items.forEach(function(x){if(cnt[x.r]!=null)cnt[x.r]++});
fl.innerHTML=['all'].concat(Object.keys(TG)).map(function(k){return'<button type="button" class="fc'+(flt===k?" on":"")+'" data-f="'+k+'">'+(k==="all"?"All":e(TG[k]))+"<i>"+cnt[k]+"</i></button>"}).join("")+'<label class="hd2"><input type="checkbox" id="hdn"'+(hideDone?" checked":"")+"> Hide done</label>"}
function vis(){return items.filter(function(x){return(flt==="all"||x.r===flt)&&!(hideDone&&x.s==="done")})}
function list(){var n=items.filter(function(x){return x.s==="new"}).length,v=vis();sub.textContent=items.length?(n?n+" new. ":"")+items.length+" message"+(items.length>1?"s":"")+", newest first.":"No messages yet. When someone writes, an envelope with a count shows at the top of Admin.";chips();
ls.innerHTML=v.length?v.map(function(x){return'<button type="button" class="it '+(x.id===cur?"on ":"")+(x.s==="new"?"nw":x.s==="done"?"dn rd":"rd")+'" data-id="'+e(x.id)+'"><span class="a">'+tag(x.r)+'<span class="w">'+e(fmt(x.at))+'</span></span><span class="s">'+e(x.sn)+'</span><span class="dv">'+e(x.d||"")+(x.k?(x.d?" \\u00b7 ":"")+"kept":"")+"</span></button>"}).join(""):'<div class="em">'+(items.length?"No messages match.":"")+"</div>"}
function show(m,msg){var del=armed===m.id,exp=m.k?"Kept until you delete it":"Deleted automatically on "+new Date(m.exp*1000).toLocaleDateString("en-GB",{timeZone:"Europe/London",day:"numeric",month:"long",year:"numeric"});
dt.innerHTML='<button type="button" class="bk" id="bk">&lsaquo; All messages</button><div class="mt"><button type="button" class="pr" data-a="'+(m.s==="done"?"undone":"done")+'">'+(m.s==="done"?"Mark as not done":"Mark done")+'</button><button type="button" data-a="'+(m.k?"unkeep":"keep")+'">'+(m.k?"Stop keeping":"Keep for good")+'</button>'+(m.from?'<a href="'+e(m.from)+'" target="_blank" rel="noopener">Open that page</a>':"")+'<button type="button" class="dg" data-a="delete">'+(del?"Press again to delete":"Delete")+'</button></div>'
+'<div class="mh"><div class="sj"><h2>'+e(subj(m.text))+"</h2>"+tag(m.r)+'</div><div class="mr"><b>From</b><span>'+(m.email?e(m.email):"Anonymous visitor (no email left)")+"</span><b>Received</b><span>"+e(fmt(m.at,true))+"</span><b>Device</b><span>"+e(m.dv||"Not recorded")+"</span><b>Page</b><span>"+(m.from?e(m.from):"Not recorded")+"</span><b>Status</b><span>"+(m.s==="done"?"Done":"Read")+"</span></div></div>"
+'<div class="bd"><div class="tx">'+e(m.text)+'</div></div><div class="msg" id="er">'+e(msg||"")+'</div><div class="ft">'+exp+"</div>";
document.getElementById("bk").onclick=function(){ib.classList.remove("sel");cur="";list()};dt.onclick=function(ev){var b=ev.target.closest("button[data-a]");if(!b)return;var a=b.getAttribute("data-a");if(a==="delete"&&armed!==m.id){armed=m.id;show(m);return}armed="";api({id:m.id,act:a},function(j){if(!j.ok){show(m,j.error||"That did not work.");return}if(a==="delete"){items=items.filter(function(x){return x.id!==m.id});cur="";ib.classList.remove("sel");dt.innerHTML='<div class="em">Deleted.</div>';list();return}var x=items.filter(function(y){return y.id===m.id})[0];if(x){x.s=j.m.s;x.k=j.m.k}show(j.m);list()})}}
ls.onclick=function(ev){var b=ev.target.closest(".it");if(!b)return;cur=b.getAttribute("data-id");armed="";ib.classList.add("sel");list();fetch("/api/inbox?msg="+encodeURIComponent(cur)).then(function(r){return r.json()}).then(function(j){if(!j.ok){dt.innerHTML='<div class="em">'+e(j.error||"That message has gone.")+"</div>";return}var x=items.filter(function(y){return y.id===cur})[0];if(x&&x.s==="new")x.s="read";show(j.m);list()}).catch(function(){dt.innerHTML='<div class="em">Could not open that message.</div>'})};
fl.onclick=function(ev){var b=ev.target.closest(".fc");if(b){flt=b.getAttribute("data-f");list();return}if(ev.target.id==="hdn"){hideDone=ev.target.checked;list()}};
function load(){if(busy)return;busy=true;var rb=document.getElementById("rf");rb.disabled=true;fetch("/api/inbox").then(function(r){return r.json()}).then(function(j){busy=false;rb.disabled=false;if(!j.ok){sub.textContent=j.error||"Could not read the messages.";return}items=(j.items||[]).slice().sort(function(a,b){return a.at<b.at?1:a.at>b.at?-1:0});list();upd.textContent="Updated "+new Date().toLocaleTimeString("en-GB",{timeZone:"Europe/London",hour:"2-digit",minute:"2-digit"})}).catch(function(){busy=false;rb.disabled=false;sub.textContent="Could not read the messages."})}
document.getElementById("rf").onclick=load;
if(${hasKv ? "true" : "false"}){load();setInterval(function(){if(!document.hidden)load()},180000);document.addEventListener("visibilitychange",function(){if(!document.hidden)load()})}else list()})();</script></body></html>`;
}
function contactInject(html, url) {
  const q = url.searchParams;
  if (url.pathname !== "/" || q.get("view") === "teams" || !(q.has("team") || q.has("view")) || ["layout", "ly", "screen", "embed", "frag", "format", "app", "s"].some(k => q.has(k)) || (q.get("device") || "").toLowerCase() === "tv") return html;
  if (/class="clubhead"|layout=tv/.test(html) || html.includes('id="sbmsg"')) return html;
  // v3.36.1: part of the page's own footer (centred above the version line) instead of floating over the content at the bottom right.
  const a = `<div id="sbmsgw" style="text-align:center;padding:14px 16px calc(16px + env(safe-area-inset-bottom));font:12px/1 Arial,Helvetica,sans-serif"><a id="sbmsg" href="/contact?from=${encodeURIComponent((url.pathname + url.search).slice(0, 200))}" style="color:rgba(128,140,134,.95);text-decoration:underline;padding:8px 6px">Message us</a></div>`;
  return html.replace(/<\/body>/i, a + "</body>");
}

// Visit counting and the Usage page (v3.10). Each counted request writes one data point to a Cloudflare Workers Analytics
// Engine dataset (binding USAGE). No cookies, no IP addresses and no typed search text are stored. A person is counted once a
