    const pos = id => near.has(String(id)) ? near.get(String(id)) + 1 : (table.findIndex(t => String(t.id) === String(id)) + 1 || null);
    const key = Math.min(hn ? near.get(String(f.hId)) : 99, an ? near.get(String(f.aId)) : 99);
