      try { const j = pr.ok ? (JSON.parse(pr.text) || {}).result : null; if (j && typeof j.latitude === "number" && typeof j.longitude === "number") loc = { latitude: j.latitude, longitude: j.longitude }; } catch (_) { /* fall through */ }
