  if (kv) {
    try { let v = await kv.get(SESSION_SECRET_KEY); if (!v || v.length < 32) { v = sbRand(32); await kv.put(SESSION_SECRET_KEY, v); } SESSION_SECRET_CACHE = v; return v; } catch (_) { /* fall through */ }
  }
